function toggleSetting(name){settings[name]=!settings[name];write(SETTINGS_KEY,settings);render();if(name==='sound'&&settings.sound)beep(1)}
function isFullscreen(){return !!(document.fullscreenElement||document.webkitFullscreenElement)}
