function showExitConfirm(destination=null,fromHistory=false){if(exitOverlay)return;exitOverlay=backdrop(`<h2>${screenText.exitTitle}</h2><p>${screenText.exitText}</p><div class="modal-actions"><button id="exitStay">${screenText.stay}</button><button class="danger-button" id="exitLeave">${screenText.leave}</button></div>`);exitOverlay.querySelector('#exitStay').onclick=()=>{closeOverlay(exitOverlay);exitOverlay=null};exitOverlay.querySelector('#exitLeave').onclick=async()=>{allowExit=true;save();cloudSync(true);try{if(isFullscreen())await (document.exitFullscreen||document.webkitExitFullscreen)?.call(document)}catch{}if(destination)location.assign(destination);else if(fromHistory)history.go(-3)}}
function boardValueAt(b,xPos,yPos){const r=b.getBoundingClientRect(),x=Math.max(0,Math.min(state.cols-1,Math.floor((xPos-r.left)/r.width*state.cols))),y=Math.max(0,Math.min(state.rows-1,Math.floor((yPos-r.top)/r.height*state.rows)));return state.board[y*state.cols+x]||0}
function bindBoard(){const b=$('#board');b.addEventListener('pointerdown',e=>{const value=boardValueAt(b,e.clientX,e.clientY);touchStart={x:e.clientX,y:e.clientY,value,long:false};clearTimeout(longPressTimer);if(value>=8192||state.rebirths)longPressTimer=setTimeout(()=>{if(!touchStart)return;touchStart.long=true;if(settings.vibration&&navigator.vibrate)navigator.vibrate(25);showNumberDetails(value)},600);b.setPointerCapture?.(e.pointerId)});b.addEventListener('pointermove',e=>{if(touchStart&&Math.max(Math.abs(e.clientX-touchStart.x),Math.abs(e.clientY-touchStart.y))>12)clearTimeout(longPressTimer)});b.addEventListener('pointerup',e=>{clearTimeout(longPressTimer);if(!touchStart)return;const start=touchStart,dx=e.clientX-start.x,dy=e.clientY-start.y;touchStart=null;if(start.long)return;if(Math.max(Math.abs(dx),Math.abs(dy))<24){showTileValue(start.value);return}move(Math.abs(dx)>Math.abs(dy)?(dx>0?1:3):(dy>0?2:0))});b.addEventListener('pointercancel',()=>{clearTimeout(longPressTimer);touchStart=null});b.addEventListener('contextmenu',e=>e.preventDefault())}
