// One history marker per open layer: Android Back dismisses UI before leaving the game.
const overlayStack=[];
let overlayBackPending=0,overlayBackTimer=null;
function trackOverlay(el,remove){
 if(!overlayBackPending)history.pushState({...(history.state||{}),ph2048Overlay:true},'',location.href);
 overlayStack.push({el,remove,marked:!overlayBackPending}); el.style.zIndex=60+overlayStack.length*2;
 paused=true;
}
function closeOverlay(el,fromHistory=false){
 const i=overlayStack.findIndex(item=>item.el===el);if(i<0)return;
 const item=overlayStack.splice(i,1)[0];item.remove();
 if(authOverlay===el)authOverlay=null;if(exitOverlay===el)exitOverlay=null;
 paused=overlayStack.length>0;
 if(!fromHistory&&item.marked){overlayBackPending++;clearTimeout(overlayBackTimer);overlayBackTimer=setTimeout(()=>history.go(-overlayBackPending),0)}
}
function showLifeLost(from,to){const copy=LIFE_MODAL[lang],classic={ru:'Ходы закончились. Убраны две самые маленькие плитки.',kk:'Жүріс қалмады. Екі ең кіші плитка жойылды.',en:'No moves remained. The two smallest tiles were removed.',fr:'Plus aucun mouvement. Les deux plus petites tuiles ont été retirées.'},text=mode==='classic'?classic[lang]:copy.text.replaceAll('{from}',from).replaceAll('{to}',to).replace('{lives}',state.lives),el=backdrop(`<h2>${copy.title}</h2><p>${text}</p><p>${state.lives} ❤️</p><div class="modal-actions"><button class="accent wide" id="lifeContinue">${copy.go}</button></div>`);el.querySelector('#lifeContinue').onclick=()=>closeOverlay(el)}
