function showMenu(){const auth=read(AUTH_KEY,null),d=drawer(t.menu,`<div class="menu-list"><button id="roomMenu">👥 ${t.room}</button><button id="shareMenu">↗ ${t.share}</button><button id="achMenu">🏆 ${t.achievements}<small>${read(ACH_KEY,[]).length} / ${A.length}</small></button><button id="rulesMenu">❔ ${t.rules}</button><button class="switch-row" id="soundMenu"><span>🔊 ${t.sound}</span><b>${settings.sound?ux.on:ux.off}</b></button><button class="switch-row" id="vibMenu"><span>📳 ${t.vibration}</span><b>${settings.vibration?ux.on:ux.off}</b></button><button class="google-login" id="googleMenu">${auth?`<img src="${esc(auth.picture)}" alt=""><span>${esc(auth.name)}<small>${esc(auth.email)}</small></span>`:`<b>G</b><span>${t.login}<small>${AUTH[lang].local}</small></span>`}</button><button id="newMenu">↻ ${t.newGame}</button></div>`);d.el.querySelector('#roomMenu').onclick=()=>{d.close();showRoom()};d.el.querySelector('#shareMenu').onclick=shareGame;d.el.querySelector('#achMenu').onclick=()=>{d.close();drawer(t.achievements,`<div class="leaderboard">${achievementsMarkup()}</div>`)};d.el.querySelector('#rulesMenu').onclick=()=>{d.close();showRules()};d.el.querySelector('#soundMenu').onclick=()=>{settings.sound=!settings.sound;write(SETTINGS_KEY,settings);d.close();showMenu()};d.el.querySelector('#vibMenu').onclick=()=>{settings.vibration=!settings.vibration;write(SETTINGS_KEY,settings);d.close();showMenu()};d.el.querySelector('#googleMenu').onclick=()=>{d.close();showAuth()};d.el.querySelector('#newMenu').onclick=()=>{d.close();confirmReset()}}
function decodeGoogleCredential(credential){try{const part=credential.split('.')[1],json=decodeURIComponent(atob(part.replace(/-/g,'+').replace(/_/g,'/')).split('').map(c=>`%${c.charCodeAt(0).toString(16).padStart(2,'0')}`).join('')),data=JSON.parse(json),aud=Array.isArray(data.aud)?data.aud:[data.aud];if(!aud.includes(GOOGLE_CLIENT_ID)||!data.sub||Number(data.exp)*1000<Date.now())return null;return{sub:String(data.sub),name:String(data.name||data.email||t.playerFallback),email:String(data.email||''),picture:String(data.picture||''),exp:Number(data.exp)}}catch{return null}}
