function renderGoogleButton(){const host=document.querySelector('#googleButton');if(!host)return;let attempts=0;const wait=setInterval(()=>{attempts++;if(window.google?.accounts?.id){clearInterval(wait);if(!googleInitialized){google.accounts.id.initialize({client_id:GOOGLE_CLIENT_ID,callback:handleGoogleCredential,ux_mode:'popup',auto_select:false,cancel_on_tap_outside:false});googleInitialized=true}host.textContent='';google.accounts.id.renderButton(host,{type:'standard',theme:'filled_black',size:'large',shape:'pill',text:'signin_with',logo_alignment:'left',width:320,locale:lang})}else if(attempts>=80){clearInterval(wait);host.textContent=AUTH[lang].error;host.classList.add('auth-error')}},100)}
function showAuth(){const copy=AUTH[lang],auth=read(AUTH_KEY,null),hasSession=!!localStorage.getItem(SESSION_KEY);authOverlay=backdrop(auth&&hasSession?`<div class="auth-profile">${auth.picture?`<img src="${esc(auth.picture)}" alt="">`:''}<h2>${esc(auth.name)}</h2><p>${esc(auth.email)}</p><p>${copy.local}</p></div><div class="modal-actions"><button id="authClose">${t.close}</button><button class="danger-button" id="googleLogout">${copy.logout}</button></div>`:`<h2>${copy.title}</h2><p>${copy.text}</p><div class="google-button" id="googleButton">${copy.loading}</div><p class="auth-note">${copy.local}</p><div class="modal-actions"><button class="wide" id="authClose">${t.close}</button></div>`);authOverlay.querySelector('#authClose').onclick=()=>{closeOverlay(authOverlay);authOverlay=null};const logout=authOverlay.querySelector('#googleLogout');if(logout)logout.onclick=async()=>{try{await api('/auth/session',{method:'DELETE'})}catch{}localStorage.removeItem(AUTH_KEY);localStorage.removeItem(SESSION_KEY);localStorage.removeItem(ROOM_KEY);room=null;window.google?.accounts?.id?.disableAutoSelect();closeOverlay(authOverlay);authOverlay=null;render();toast(copy.logout)};else renderGoogleButton()}
async function shareGame(){const url=`${location.origin}${location.pathname}`,data={title:'2048 PortHub',text:`${t.shareText} ${t.statusLives.replace('{score}',fmt(state.score)).replace('{tile}',tileLabel(maxTile())).replace('{lives}','❤️'.repeat(state.lives))}`,url};try{if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(`${data.text} ${url}`);toast(t.copied)}}catch(e){if(e?.name!=='AbortError')toast(t.copied)}}
function profile(){let p=read(PROFILE_KEY,null);if(!p){p={id:crypto.randomUUID?.()||Math.random().toString(36).slice(2),name:''};write(PROFILE_KEY,p)}return p}
async function api(path,options={}){const session=localStorage.getItem(SESSION_KEY),headers={'content-type':'application/json',...(!options.anonymous&&session?{authorization:`Bearer ${session}`} :{}),...(options.headers||{})};const ctl=new AbortController(),timeout=setTimeout(()=>ctl.abort(),8000);try{const res=await fetch(`${API}${path}`,{...options,headers,signal:ctl.signal});const data=await res.json().catch(()=>({}));if(!res.ok){const e=new Error(data.error||String(res.status));e.status=res.status;e.data=data;throw e}return data}finally{clearTimeout(timeout)}}
function roomFormText(){return `<div class="room-card"><p>${t.roomOfflineText}</p><label>${t.yourName}<input id="playerName" maxlength="24" value="${esc(profile().name)}" autocomplete="nickname"></label><label>${t.roomName}<input id="roomName" maxlength="40" value="PortHub Friends" autocomplete="off"></label><button class="primary" id="createRoom">👥 ${t.createRoom}</button></div>`}
async function showRoom(){if(!localStorage.getItem(SESSION_KEY)){showAuth();return}const d=drawer(t.room,`<div id="roomsPanel"><p>…</p></div>`),panel=d.el.querySelector('#roomsPanel');try{const data=await api('/rooms');roomsCache=data.rooms||[];const active=roomsCache.find(x=>x.roomId===room?.roomId)||roomsCache[0];if(active){room={...room,...active};write(ROOM_KEY,room);panel.innerHTML=`<div class="room-switcher"><b>${data.count} / ${data.limit}</b>${roomsCache.map(x=>`<button class="room-choice${x.roomId===room.roomId?' active':''}" data-id="${esc(x.roomId)}">${esc(x.name)} <small>${x.memberCount} 👥</small></button>`).join('')}</div><div class="room-card"><h3 id="activeRoomName">${esc(room.name)}</h3><p>${Date.now()-room.updatedAt>7776e6?(ux.inactive):t.updated.replace('{n}',new Date(room.updatedAt).toLocaleDateString(lang))}</p><button class="primary" id="inviteRoom">↗ ${t.invite}</button><button id="renameRoom">✎ ${ux.rename}</button></div><div class="leaderboard" id="leaders"><p>${t.leaderEmpty}</p></div><button id="createAnother">＋ ${t.createRoom}</button><div class="room-danger-zone"><button class="danger-button" id="leaveRoom">${ux.leave}</button></div>`;panel.querySelectorAll('.room-choice').forEach(b=>b.onclick=()=>{room={...roomsCache.find(x=>x.roomId===b.dataset.id),lastSync:0};write(ROOM_KEY,room);d.close();render();showRoom()});panel.querySelector('#inviteRoom').onclick=shareRoomInvite;panel.querySelector('#createAnother').onclick=()=>showCreateRoom(d);panel.querySelector('#renameRoom').onclick=async()=>{const name=prompt(t.roomName,room.name);if(name){await api(`/rooms/${encodeURIComponent(room.roomId)}`,{method:'PATCH',body:JSON.stringify({name})});room.name=name;write(ROOM_KEY,room);d.close();showRoom()}};panel.querySelector('#leaveRoom').onclick=()=>leaveCurrentRoom(d);loadRoom(panel.querySelector('#leaders'));return}panel.innerHTML=roomFormText();bindCreateRoom(panel,d)}catch{panel.innerHTML=`<p>${t.roomOfflineText}</p>`}}
