function bindCreateRoom(panel,d){panel.querySelector('#createRoom').onclick=async()=>{const button=panel.querySelector('#createRoom'),name=panel.querySelector('#playerName').value.trim()||t.playerFallback,roomName=panel.querySelector('#roomName').value.trim()||ux.roomDefault;button.disabled=true;try{const created=await api('/rooms',{method:'POST',body:JSON.stringify({name:roomName,displayName:name})});room={...created,lastSync:0};write(ROOM_KEY,room);d.close();render();showRoom()}catch(e){button.disabled=false;button.textContent=e.message==='room_limit'?'10 / 10':t.retry}}}
