async function leaveCurrentRoom(d){
  const target=room?.roomId;if(!target)return;
  const el=backdrop(`<h2>${ux.leaveTitle}</h2><p>${ux.leaveText}</p><div id="ownerTransfer"></div><div class="modal-actions"><button id="leaveCancel">${t.cancel}</button><button class="danger-button" id="leaveConfirm" disabled>${ux.leave}</button></div>`);
  el.querySelector('#leaveCancel').onclick=()=>closeOverlay(el);
  try{
    const info=await api(`/rooms/${encodeURIComponent(target)}?game=2048&mode=${mode}`);
    if(!el.isConnected)return;
    const others=info.members.filter(x=>x.id!==info.userId),transfer=info.room.ownerUserId===info.userId&&others.length>0;
    if(transfer)el.querySelector('#ownerTransfer').innerHTML=`<label>${ux.owner}<select id="successor"><option value="">—</option>${others.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></label>`;
    const button=el.querySelector('#leaveConfirm'),select=el.querySelector('#successor');
    button.disabled=transfer;if(select)select.onchange=()=>button.disabled=!select.value;
    button.onclick=async()=>{button.disabled=true;try{await api(`/rooms/${encodeURIComponent(target)}/members/me`,{method:'DELETE',body:JSON.stringify({successorUserId:select?.value||''})});room=null;localStorage.removeItem(ROOM_KEY);closeOverlay(el);d.close();render();showRoom()}catch{button.disabled=false;toast(t.retry)}};
  }catch{el.querySelector('#ownerTransfer').textContent=t.roomOfflineText}
}
async function loadRoom(container){try{const data=await api(`/rooms/${encodeURIComponent(room.roomId)}?game=2048&mode=${encodeURIComponent(mode)}`),owner=data.room.ownerUserId===data.userId,flagged=data.leaderboard?.some(x=>x.review),notice=flagged?`<div class="review-note"><b>${REVIEW[lang].title}</b><span>${REVIEW[lang].text}</span></div>`:'',leaders=data.leaderboard?.length?data.leaderboard.map((x,i)=>`<div class="leader${x.review?' review':''}"><b>${x.review?'🚨':i+1}</b><span>${esc(x.name)}<small>${fmt(x.score)} · ★${x.rebirths||0} · ${tileLabel(x.maxTile)} · ${numberLevel(Math.round(Math.log2(Math.max(2,x.maxTile)))+10*(x.rebirths||0))}</small></span><strong>${fmt(x.score)}</strong></div>`).join(''):`<p>${t.leaderEmpty}</p>`,members=owner?`<div class="members-admin"><b>${ux.members}</b>${data.members.filter(x=>x.id!==data.userId).map(x=>`<div><span>${esc(x.name)}</span><button class="kick-member" data-id="${esc(x.id)}">${ux.remove}</button></div>`).join('')}</div>`:'';container.innerHTML=notice+leaders+members;if(!owner)container.closest('#roomsPanel')?.querySelector('#renameRoom')?.remove();container.querySelectorAll('.kick-member').forEach(b=>b.onclick=async()=>{if(!confirm(ux.removeConfirm))return;await api(`/rooms/${encodeURIComponent(room.roomId)}/members/${encodeURIComponent(b.dataset.id)}`,{method:'DELETE'});loadRoom(container)})}catch{container.innerHTML=`<p>${t.roomOfflineText}</p>`}}
async function cloudSync(force=false,status='playing'){if(!localStorage.getItem(SESSION_KEY)||cloudBusy)return;const interval=Math.max(60,Number(room?.syncAfter)||120)*1000;if(!force&&Date.now()-lastCloudSync<interval)return;cloudBusy=true;const p=profile(),platform=navigator.userAgentData?.platform||navigator.platform||'Web';try{const data=await api(`/runs/${encodeURIComponent(state.runId)}`,{method:'PUT',keepalive:force,body:JSON.stringify({game:'2048',deviceId:p.id,deviceLabel:platform,platform,expectedRevision:state.cloudRevision||0,status,state})});state.cloudRevision=data.revision;lastCloudSync=Date.now();if(room){room.syncAfter=data.syncAfter||120;write(ROOM_KEY,room)}save()}catch(e){if(e.status===409&&e.data?.remote)showCloudConflict(e.data.remote)}finally{cloudBusy=false}}
function showCloudConflict(remote){if(paused)return;const el=backdrop(`<h2>${ux.conflict}</h2><p>${ux.conflictText}</p><div class="modal-actions"><button id="useCloud">${ux.cloud}</button><button id="forkLocal">${ux.both}</button></div>`);el.querySelector('#useCloud').onclick=()=>{const next=normalizeState(remote.state);if(next){state=next;state.cloudRevision=remote.revision;save();render()}closeOverlay(el)};el.querySelector('#forkLocal').onclick=()=>{state.runId=newRunId();state.cloudRevision=0;save();closeOverlay(el);cloudSync(true)}}
async function reconcileCloud(){if(!localStorage.getItem(SESSION_KEY))return;try{const data=await api(`/runs?game=2048&mode=${encodeURIComponent(mode)}`),same=data.runs.find(x=>x.runId===state.runId),fresh=data.runs.find(x=>x.status==='playing'&&x.state&&x.runId!==state.runId);if(same&&same.revision>(state.cloudRevision||0))showCloudConflict(same);else if(!same&&fresh&&state.moves===0)showCloudConflict(fresh);else cloudSync(true)}catch{}}
function inviteData(){const roomId=new URLSearchParams(location.search).get('room'),key=new URLSearchParams(location.hash.slice(1)).get('key');return roomId&&key?{roomId,key}:null}
