function maybeCoffee(created){const milestone=[2048,8192].find(v=>created.includes(v)&&!state.shownPauses.includes(v));if(!milestone)return;state.shownPauses.push(milestone);save();showCoffee()}
function showCoffee(){const el=backdrop(`<h2>📺 ${t.coffeeTitle}</h2><p>${t.coffeeText}</p><div class="modal-actions"><a href="${SUPPORT.boosty}" target="_blank" rel="noopener">☕ ${t.boosty}</a><a href="${SUPPORT.kofi}" target="_blank" rel="noopener">☕ ${t.kofi}</a><button id="sharePause">↗ ${t.share}</button><button id="roomPause">👥 ${room?t.invite:t.createInvite}</button><button class="accent wide countdown" id="continuePause" disabled>${t.continue.replace('{n}',10)}</button></div>`);el.querySelector('#sharePause').onclick=shareGame;el.querySelector('#roomPause').onclick=()=>{closeOverlay(el);showRoom()};const b=el.querySelector('#continuePause');let n=10;const tick=setInterval(()=>{if(!el.isConnected){clearInterval(tick);return}n--;b.textContent=n?t.continue.replace('{n}',n):t.continueNow;if(!n){clearInterval(tick);b.disabled=false;b.onclick=()=>closeOverlay(el)}},1000)}
